  FT["PH-H8206"] = {"id":"PH-H8206","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2009/ra_9748_2009.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Puerto Princesa市","en":"An Act Declaring the Twenty-third of June of Every Year a Special Nonworking Public Holiday in the Entire Province of Palawan and the City of Puerto Princesa","orig":"An Act Declaring the Twenty-third of June of Every Year a Special Nonworking Public Holiday in the Entire Province of Palawan and the City of Puerto Princesa"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 9748","issuingBody":"Congress of the Philippines","promulgatedDate":"2009-11-10","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2009/ra_9748_2009.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8206-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"In commemoration of the \"Foundation of the First Civil Government of the Province of Palawan after the American-Philippine War\", June 23 of every year is hereby declared as a \"Special Nonworking Public Holiday in the Province of Palawan and the City of Puerto Princesa\"."}},{"id":"PH-H8206-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p117"};
  FT["PH-H8207"] = {"id":"PH-H8207","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2009/ra_9749_2009.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"宣布每年7月31日（Paye战役日）为马林杜克省特别非工作日假日的法案","en":"An Act Declaring July 31 - Battle of Paye Day - of Every Year as a Special Nonworking Holiday in the Province of Marinduque","orig":"An Act Declaring July 31 - Battle of Paye Day - of Every Year as a Special Nonworking Holiday in the Province of Marinduque"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 9749","issuingBody":"Congress of the Philippines","promulgatedDate":"2009-11-10","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2009/ra_9749_2009.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8207-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"July 31 of every year is hereby declared a special nonworking holiday in the entire Province of Marinduque to commemorate the victory of Filipino revolutionists in the Battle of Paye that took place on July 31, 1900."}},{"id":"PH-H8207-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The provincial government of Marinduque and the Municipal Government of Boac, in coordination with the National Historical Institute, shall lead appropriate and meaningful commemorative programs and activities to be participated in by officials and employees of the national, provincial and municipal government agencies and instrumentalities, and civic, religious, nongovernment, business and civil society organizations, in order to give significance and honor to the heroes and heroines of the Battle of Paye."}},{"id":"PH-H8207-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p117","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Declaring July 31 - Battle of Paye Day - of Every Year as a Special Nonworking Holiday in the Province of Marinduque","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8208"] = {"id":"PH-H8208","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2009/ra_9750_2009.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立San Jose Del Monte市","en":"The Foundation Day of the City of San Jose Del Monte","orig":"An Act Declaring September 10 of Every Year a Special Nonworking Holiday in the City of San Jose Del Monte, Province of Bulacan to Be Known as \"The Foundation Day of the City of San Jose Del Monte\"","vi":"Ngày Thành lập Thành phố San Jose Del Monte","th":"วันสถาปนาเมือง San Jose Del Monte","id":"Hari Jadi Kota San Jose Del Monte","ms":"Hari Penubuhan Bandaraya San Jose Del Monte"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 9750","issuingBody":"Congress of the Philippines","promulgatedDate":"2009-11-10","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2009/ra_9750_2009.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8208-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"September 10 of every year is hereby declared to be a special nonworking holiday in the City of San Jose del Monte, Province of Bulacan to commemorate its founding day and to be known as The \"Foundation Day of the City of San Jose del Monte\"."}},{"id":"PH-H8208-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p117"};
  FT["PH-H8209"] = {"id":"PH-H8209","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2009/ra_9751_2009.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将马斯巴特省Malinta-Lagta公路改设为国道的法案","en":"An Act Converting the Malinta-Lagta Road, Province of Masbate into a National Road","orig":"An Act Converting the Malinta-Lagta Road, Province of Masbate into a National Road"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 9751","issuingBody":"Congress of the Philippines","promulgatedDate":"2009-11-10","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2009/ra_9751_2009.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8209-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Malinta-Lagta Road which traverses Barangay Malinta in Masbate City and Barangay Lagta in the Municipality of Bale no, Province of Masbate is hereby converted into a national road."}},{"id":"PH-H8209-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Public Works and High ways shall issue the necessary rules, orders and circulars to implement the provision of this Act."}},{"id":"PH-H8209-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in a newspaper of general circulation."}}],"pack":"ph-p117","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Converting the Malinta-Lagta Road, Province of Masbate into a National Road","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
