  FT["PH-H8211"] = {"id":"PH-H8211","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2009/ra_9753_2009.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"设立Balilihan市","en":"An Act Converting the Congressman Pablo Malasarte Memorial High School in Barangay Cabad, Municipality of Balilihan, Province of Bohol into a National High School to Be Known as Congressman Pablo Malasarte National High School and Appropriating Funds Therefor","orig":"An Act Converting the Congressman Pablo Malasarte Memorial High School in Barangay Cabad, Municipality of Balilihan, Province of Bohol into a National High School to Be Known as Congressman Pablo Malasarte National High School and Appropriating Funds Therefor","vi":"Đạo luật chuyển đổi Congressman Pablo Malasarte Memorial High School thành Congressman Pablo Malasarte National High School","th":"พระราชบัญญัติเปลี่ยนสถานะ Congressman Pablo Malasarte Memorial High School เป็น Congressman Pablo Malasarte National High School","id":"Undang-Undang mengubah Congressman Pablo Malasarte Memorial High School menjadi Congressman Pablo Malasarte National High School","ms":"Akta menukar Congressman Pablo Malasarte Memorial High School kepada Congressman Pablo Malasarte National High School"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 9753","issuingBody":"Congress of the Philippines","promulgatedDate":"2009-11-10","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2009/ra_9753_2009.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8211-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Conversion into a National High School. - The Congressman Pablo Malasarte Memorial High School in Barangay Cabad, Municipality of Balilihan, Province of Bohol is hereby converted into a national high school to be known as Congressman Pablo Malasarte National High School."}},{"id":"PH-H8211-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Transfer of Assets and Liabilities. - All personnel, assets, liabilities and records of the Congressman Pablo Malasarte Memorial High School are hereby transferred to and absorbed by the Congressman Pablo Malasarte National High School."}},{"id":"PH-H8211-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Appropriations. - The Secretary of Education shall immediately include in the Department's program the operationalization ofthe Congressman Pablo Malasarte National High School, the initial funding of which shall be charged against the current year's appropriations of the Congressman Pablo Malasarte Memorial High School. Thereafter, the amount necessary for the continued operation of the school shall be included in the annual General Appropriations Act."}},{"id":"PH-H8211-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Implementation. - The Secretary of Education shall issue such rules and regulations as may be necessary to carry out the provisions of this Act."}},{"id":"PH-H8211-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Effectivity. - This Act shall take effect fifteen (15) days after its publication in the Official Gazette."}}],"pack":"ph-p117"};
  FT["PH-H8212"] = {"id":"PH-H8212","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2009/ra_9754_2009.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将奎松省圣纳西索镇圣纳西索职业中学的名称变更为Godofredo M. Tan纪念工艺学校的法案","en":"An Act Changing the Name of San Narciso Vocational High School in San Narciso, Province of Quezon to Godofredo M. Tan Memorial School of Arts and Trades","orig":"An Act Changing the Name of San Narciso Vocational High School in San Narciso, Province of Quezon to Godofredo M. Tan Memorial School of Arts and Trades","vi":"Đạo luật đổi tên San Narciso Vocational High School in San Narciso, Province of Quezon thành Godofredo M. Tan Memorial School of Arts and Trades","th":"พระราชบัญญัติเปลี่ยนชื่อ San Narciso Vocational High School in San Narciso, Province of Quezon เป็น Godofredo M. Tan Memorial School of Arts and Trades","id":"Undang-Undang mengubah nama San Narciso Vocational High School in San Narciso, Province of Quezon menjadi Godofredo M. Tan Memorial School of Arts and Trades","ms":"Akta menukar nama San Narciso Vocational High School in San Narciso, Province of Quezon menjadi Godofredo M. Tan Memorial School of Arts and Trades"},"level":"law","status":"active","topics":["education","culture"],"docNumber":"Republic Act No. 9754","issuingBody":"Congress of the Philippines","promulgatedDate":"2009-11-10","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2009/ra_9754_2009.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8212-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Renaming of High School. - The name of San Narciso Vocational High School in the Municipality of San Narciso, Province of Quezon is hereby changed to Godofredo M. Tan Memorial School of Arts and Trades."}},{"id":"PH-H8212-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Effectivity. - This Act shall take effect fifteen (15) days after its publication in the Official Gazette."}}],"pack":"ph-p117","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of San Narciso Vocational High School in San Narciso, Province of Quezon to Godofredo M. Tan Memorial School of Arts and Trades","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8213"] = {"id":"PH-H8213","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2009/ra_9755_2009.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Socorro市","en":"An Act Establishing a National High School in Barangay Fortuna, Municipality of Socorro, Province of Oriental Mindoro to Be Known as Fortuna National High School and Appropriating Funds Therefor","orig":"An Act Establishing a National High School in Barangay Fortuna, Municipality of Socorro, Province of Oriental Mindoro to Be Known as Fortuna National High School and Appropriating Funds Therefor","vi":"Đạo luật thành lập Trường trung học phổ thông quốc gia tại Barangay Fortuna, Thị trấn Socorro, Tỉnh Oriental Mindoro được biết đến với tên gọi Trường trung học phổ thông quốc gia Fortuna","th":"พระราชบัญญัติจัดตั้งโรงเรียนมัธยมศึกษาตอนปลายแห่งชาติในบารังไกย์ Fortuna, เทศบาล Socorro, จังหวัด Oriental Mindoro ให้เป็นที่รู้จักในชื่อโรงเรียนมัธยมศึกษาตอนปลายแห่งชาติ Fortuna","id":"Undang-Undang mendirikan Sekolah Menengah Atas Nasional di Barangay Fortuna, Kotamadya Socorro, Provinsi Oriental Mindoro dikenal sebagai Sekolah Menengah Atas Nasional Fortuna","ms":"Akta menubuhkan Sekolah Menengah Kebangsaan di Barangay Fortuna, Perbandaran Socorro, Wilayah Oriental Mindoro dikenali sebagai Sekolah Menengah Kebangsaan Fortuna"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 9755","issuingBody":"Congress of the Philippines","promulgatedDate":"2009-11-10","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2009/ra_9755_2009.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8213-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Establishment of a National High School. - There is hereby established, under the supervision of the Department of Education, a national high school in Barangay Fortuna, Municipality of Socorro, Province of Oriental Mindoro to be known as Fortuna National High School."}},{"id":"PH-H8213-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Appropriations. - The Secretary of Education shall immediately include in the Department's program the operationalization of Fortuna National High School, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H8213-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Implementation. - The Secretary of Education shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H8213-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Effectivity. - This Act shall take effect fifteen (15) days after its publication in the Official Gazette."}}],"pack":"ph-p117"};
